describe('Video Player Responsive Resize on Tablet Viewports', () => {
  beforeEach(() => {
    cy.visit('/video-player');
  });

  it('should resize video player proportionally when viewport width changes to tablet size', () => {
    // Verify video player is visible on desktop viewport
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').should('have.css', 'width', '1000px');
    cy.get('[data-testid="video-player"]').should('have.css', 'height', '562.5px');

    // Change viewport to tablet size (768px width)
    cy.viewport('768', '1020');

    // Verify video player resizes proportionally
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').should('have.css', 'width', '100%');
    cy.get('[data-testid="video-player"]').should('have.css', 'height', 'auto');

    // Verify aspect ratio is maintained (16:9)
    cy.get('[data-testid="video-player"]').then(($player) => {
      const width = $player.width();
      const height = $player.height();
      const aspectRatio = width / height;
      expect(aspectRatio).to.be.closeTo(16 / 9, 0.01);
    });

    // Verify video controls are still functional
    cy.get('[data-testid="play-button"]').should('be.visible');
    cy.get('[data-testid="play-button"]').click();
    cy.get('[data-testid="video-player"]').should('contain', 'playing');
  });

  it('should handle video player resize gracefully when viewport is too narrow', () => {
    // Change viewport to mobile size (320px width)
    cy.viewport('320', '600');

    // Verify video player still displays and maintains aspect ratio
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').should('have.css', 'width', '100%');
    cy.get('[data-testid="video-player"]').should('have.css', 'height', 'auto');

    // Verify aspect ratio is maintained
    cy.get('[data-testid="video-player"]').then(($player) => {
      const width = $player.width();
      const height = $player.height();
      const aspectRatio = width / height;
      expect(aspectRatio).to.be.closeTo(16 / 9, 0.01);
    });

    // Verify video controls are still accessible and functional
    cy.get('[data-testid="play-button"]').should('be.visible');
    cy.get('[data-testid="volume-control"]').should('be.visible');
    cy.get('[data-testid="volume-control"]').click();
    cy.get('[data-testid="volume-slider"]').should('be.visible');

    // Verify video can be paused
    cy.get('[data-testid="pause-button"]').click();
    cy.get('[data-testid="video-player"]').should('contain', 'paused');
  });
});
